`border-brand-one focus-visible:border-brand-one mt-2 h-auto rounded-full border bg-transparent px-6 py-2 text-xl! focus-visible:ring-0 ${
                    touched.name && errors.name
                      ? "border-red-500 focus-visible:border-red-500"
                      : ""
                  }`

`border-brand-one focus-visible:border-brand-one mt-2 h-auto rounded-full border bg-transparent px-6 py-2 text-xl! focus-visible:ring-0 ${
                    touched.email && errors.email
                      ? "border-red-500 focus-visible:border-red-500"
                      : ""
                  }`

`border-brand-one focus-visible:border-brand-one mt-2 h-auto rounded-full border bg-transparent px-6 py-2 text-xl! focus-visible:ring-0 ${
                    touched.phone && errors.phone
                      ? "border-red-500 focus-visible:border-red-500"
                      : ""
                  }`

`border-brand-one focus-visible:border-brand-one mt-2 min-h-50 rounded-md border bg-transparent px-6 py-2 text-xl! focus-visible:ring-0 ${
                    touched.message && errors.message
                      ? "border-red-500 focus-visible:border-red-500"
                      : ""
                  }`

`border-brand-three focus-visible:border-brand-three mt-2 h-auto rounded-full border bg-transparent px-6 py-2 text-xl! focus-visible:ring-0 ${
                    touched.name && errors.name
                      ? "border-red-500 focus-visible:border-red-500"
                      : ""
                  }`

`border-brand-three focus-visible:border-brand-three mt-2 h-auto rounded-full border bg-transparent px-6 py-2 text-xl! focus-visible:ring-0 ${
                    touched.email && errors.email
                      ? "border-red-500 focus-visible:border-red-500"
                      : ""
                  }`

`border-brand-three focus-visible:border-brand-three mt-2 h-auto rounded-full border bg-transparent px-6 py-2 text-xl! focus-visible:ring-0 ${
                    touched.phone && errors.phone
                      ? "border-red-500 focus-visible:border-red-500"
                      : ""
                  }`

`border-brand-three focus-visible:border-brand-three mt-2 min-h-50 rounded-md border bg-transparent px-6 py-2 text-xl! focus-visible:ring-0 ${
                    touched.message && errors.message
                      ? "border-red-500 focus-visible:border-red-500"
                      : ""
                  }`

`bg-brand-one fixed right-8 bottom-8 z-50 h-14 w-14 rounded-full shadow-lg transition-all duration-300 hover:scale-110 ${
        isVisible
          ? "translate-y-0 opacity-100"
          : "pointer-events-none translate-y-10 opacity-0"
      }`

`group flex h-full w-full flex-col gap-4 rounded-xl py-8 duration-3000 ease-in-out sm:gap-5 ${
                      isActive ? "scale-100 opacity-100" : "scale-80 opacity-50"
                    }`

`group flex h-full w-full flex-col gap-4 rounded-xl py-8 duration-3000 ease-in-out sm:gap-5 ${
                      isActive ? "scale-100 opacity-100" : "scale-80 opacity-50"
                    }`

`relative flex items-center justify-center overflow-visible ${
                isLargeScreen ? "h-125 w-auto" : "h-30 w-125"
              }`

`bg-primary-foreground flex h-20 w-20 cursor-pointer items-center justify-center overflow-hidden rounded-full border-2 transition-colors duration-300 ${
                            isActive
                              ? "shadow-lg"
                              : "border-white/20 hover:border-white/40"
                          }`

`flex w-full items-center justify-between rounded-lg border px-4 py-3 text-left focus:ring-2 focus:ring-black focus:outline-none ${
                    touched.partnerType && errors.partnerType
                      ? "border-red-500 focus:ring-red-500"
                      : "border-gray-300"
                  } ${!formData.partnerType ? "text-gray-400" : "text-gray-900"}`

`w-full px-4 py-3 text-left text-sm hover:bg-gray-50 ${
                            formData.partnerType === option.value
                              ? "font-semibold text-black"
                              : "text-gray-700"
                          }`

`mt-6 rounded-full px-10 py-4 font-semibold transition-colors duration-200 ${
                isSubmitting
                  ? "cursor-not-allowed bg-gray-200 text-gray-400"
                  : "cursor-pointer bg-black text-white hover:bg-gray-800"
              }`
